class DeviceControl{constructor(){this.verificarDispositivo(),window.addEventListener("resize",()=>this.verificarDispositivo())}verificarDispositivo(){window.innerWidth>=768?this.exibirElementosDesktop():this.exibirElementosMobile()}exibirElementosDesktop(){document.querySelector(".body-desktop").classList.remove("hidden"),document.querySelector(".body-desktop").classList.add("visible"),document.querySelector(".body-mobile").classList.remove("visible"),document.querySelector(".body-mobile").classList.add("hidden")}exibirElementosMobile(){document.querySelector(".body-mobile").classList.remove("hidden"),document.querySelector(".body-mobile").classList.add("visible"),document.querySelector(".body-desktop").classList.remove("visible"),document.querySelector(".body-desktop").classList.add("hidden")}}window.onload=()=>new DeviceControl;